#!/usr/bin/env python3
"""Compressed bootstrap for candidate 2c.

The workflow materializes the readable policy before execution and publishes it with
research evidence. Importing this bootstrap exposes ``COMPRESSED_SOURCE`` without
importing optional modeling dependencies.
"""
import base64
import gzip

COMPRESSED_SOURCE = ''

def _execute() -> None:
    source = gzip.decompress(base64.b64decode(COMPRESSED_SOURCE))
    exec(compile(source, __file__, "exec"), globals(), globals())

if __name__ == "__main__":
    _execute()
